function getRunwayTranslation(key, lang) {
    if (runwayTranslations[lang] && runwayTranslations[lang][key]) {
        return runwayTranslations[lang][key];
    }
    // Fallback à l'anglais
    if (runwayTranslations.en && runwayTranslations.en[key]) {
        return runwayTranslations.en[key];
    }
    return null;
}

// Appliquer les traductions runway
function applyRunwayTranslations(lang) {
    

    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');

        // Seulement pour les clés runway
        if (key && (key.startsWith('review.runway.') || key.startsWith('review.common.'))) {
            const translation = getRunwayTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });

    
}

// Auto-appliquer quand la langue change
document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyRunwayTranslations(lang), 200);
});

// Appliquer au chargement
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyRunwayTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyRunwayTranslations(currentLang);
}


